public final class Stabilization269 {
 static ServerLevel w;static ServerPlayer p;static SivkaEntity h;static int ticks,caseTick,which;static double y0,peak,maxSpeed;static long start,pre;static boolean done,extended;static String current="bootstrap";static final List<Map<String,Object>> checks=new ArrayList<>();static final List<Long> times=new ArrayList<>();static final Map<String,Object> out=new LinkedHashMap<>();
 static final class Conn extends net.minecraft.network.Connection {final io.netty.channel.embedded.EmbeddedChannel c=new io.netty.channel.embedded.EmbeddedChannel();Conn(){super(net.minecraft.network.protocol.PacketFlow.SERVERBOUND);}@Override public io.netty.channel.Channel channel(){return c;}}
 static final class Listener extends net.minecraft.server.network.ServerGamePacketListenerImpl{Listener(ServerPlayer p){super(p.server,new Conn(),p,net.minecraft.server.network.CommonListenerCookie.createInitial(p.getGameProfile(),false));}@Override public void send(net.minecraft.network.protocol.Packet<?> q){}@Override public void send(net.minecraft.network.protocol.Packet<?> q,net.minecraft.network.PacketSendListener l){}}
 static void check(boolean ok,String name){checks.add(Map.of("system",current,"test",name,"status",ok?"PASS":"FAIL"));System.out.println("QA269 "+(ok?"PASS ":"FAIL ")+current+" "+name);}
 @SuppressWarnings("unchecked") static ServerPlayer player(String name)throws Exception{var p=new ServerPlayer(w.getServer(),w,new com.mojang.authlib.GameProfile(UUID.nameUUIDFromBytes(name.getBytes()),name),ClientInformation.createDefault());p.connection=new Listener(p);p.setGameMode(GameType.SURVIVAL);p.moveTo(1000.5,201,0.5);p.setNoGravity(true);w.addNewPlayer(p);var f=net.minecraft.server.players.PlayerList.class.getDeclaredField("playersByUUID");f.setAccessible(true);((Map<UUID,ServerPlayer>)f.get(w.getServer().getPlayerList())).put(p.getUUID(),p);return p;}
 static void registry()throws Exception{var result=new LinkedHashMap<String,Object>();for(var pair:List.of(Map.entry("items",BuiltInRegistries.ITEM),Map.entry("entities",BuiltInRegistries.ENTITY_TYPE),Map.entry("blocks",BuiltInRegistries.BLOCK),Map.entry("menus",BuiltInRegistries.MENU),Map.entry("effects",BuiltInRegistries.MOB_EFFECT))){var ids=pair.getValue().keySet().stream().filter(k->k.getNamespace().equals("slavicmyths")).map(Object::toString).sorted().toList();result.put(pair.getKey(),ids);}var biomes=w.getServer().getLevel(Level.NETHER).getChunkSource().getGenerator().getBiomeSource().possibleBiomes().stream().map(b->b.unwrapKey().orElseThrow().location().toString()).filter(s->s.startsWith("slavicmyths:")).toList();result.put("nether_biomes",biomes);out.put("registry",result);}
 static void scene(int mode)throws Exception{if(mode!=0)for(int z=-1;z<=16;z++){w.getChunk(62,z);w.setChunkForced(62,z,true);}if(h!=null){p.stopRiding();h.discard();}p.moveTo(1000.5,201,.5);h=SivkaContent.ENTITY.get().create(w);h.moveTo(1000.5,201,.5);var bond=new SivkaBonds.Bond(p.getUUID());bond.stage=7;bond.entity=h.getUUID();bond.last=h.blockPosition();SivkaBonds.get(w).bonds.put(p.getUUID(),bond);SivkaBonds.get(w).setDirty();h.owner=p.getUUID();h.bond=bond.id;h.generation=bond.generation;w.addFreshEntity(h);h.setOnGround(true);p.startRiding(h,true);if(mode!=0){var tag=new CompoundTag();h.addAdditionalSaveData(tag);tag.putBoolean("SivkaAirborne",true);h.readAdditionalSaveData(tag);h.setPos(1000.5,220,.5);h.setOnGround(false);}caseTick=0;y0=h.getY();peak=y0;maxSpeed=0;}
 static void yaga()throws Exception{current="yaga_access";check(!YagaDiscovery.eligible(p),"new Survival has no unearned Yaga access");p.setGameMode(GameType.CREATIVE);check(YagaDiscovery.eligible(p),"actual Creative mode hook opens search");p.setGameMode(GameType.SURVIVAL);check(YagaDiscovery.eligible(p),"return Survival preserves search");check(YagaData.get(w).progress(p.getUUID()).stage==0,"Creative does not award trust");check(YagaDiscovery.create(p,null),"real Yaga discovery job accepted");}
 static void services()throws Exception{current="yaga_services";var d=YagaData.get(w);var npc=(BabaYaga)w.getEntity(d.npc);check(npc!=null&&npc.canonical(),"actual canonical Yaga NPC exists");if(npc==null)return;p.stopRiding();p.moveTo(npc.position().add(1,0,0));var progress=d.progress(p.getUUID());progress.intro=2;progress.stage=3;d.setDirty();
  for(int r=0;r<YagaServices.BREWS.length;r++){var e=YagaServices.BREWS[r];var menu=new YagaMenu(1,p.getInventory(),npc.getId());menu.clickMenuButton(p,3);menu.clickMenuButton(p,500+r);check(!menu.clickMenuButton(p,600),"brew rejects missing ingredients "+e.id);for(int i=0;i<4;i++)menu.input.setItem(i,new ItemStack(e.inputs[i].item(),e.inputs[i].count));check(menu.clickMenuButton(p,600),"actual brew success "+e.id);check(ItemStack.isSameItemSameComponents(menu.input.getItem(4),e.output())&&menu.input.getItem(4).getCount()==e.amount,"correct brew output "+e.id);check(!menu.clickMenuButton(p,600),"repeat missing-input brew rejected "+e.id);menu.removed(p);}
  for(int i=0;i<YagaServices.EXCHANGES.length;i++){var e=YagaServices.EXCHANGES[i];p.getInventory().clearContent();p.getPersistentData().remove("YagaExchangeUntil");for(var n:e.inputs)p.getInventory().add(new ItemStack(n.item(),n.count));var menu=new YagaMenu(1,p.getInventory(),npc.getId());boolean ok=menu.clickMenuButton(p,400+i);check(e.id.equals("veles_oath_iv")?!ok:ok,"exchange actual inputs/gate "+e.id);if(ok){p.getPersistentData().remove("YagaExchangeUntil");check(!menu.clickMenuButton(p,400+i),"no repeat exchange without inputs "+e.id);}menu.removed(p);}
  current="locate_read_only";var records=org.slavicmyths.worldgen.ManualStructureRecords.get(w);int count=records.entries().size();var source=p.createCommandSourceStack().withPermission(4).withPosition(new Vec3(40000,180,40000));for(String id:List.of("kurgan_small","kurgan_warrior","kurgan_great","bandit_camp_small","bandit_camp_medium","bandit_camp_large","swamp_hut","fishing_camp","flooded_shrine"))org.slavicmyths.worldgen.OnDemandStructures.locate(source,id);check(records.entries().size()==count&&org.slavicmyths.worldgen.ManualStructureJobs.status(source)==0,"all small/camp/kurgan locate calls create no record/job");var jobs=org.slavicmyths.worldgen.TemplateSiteJobs.class.getDeclaredField("JOBS");jobs.setAccessible(true);check(((Map<?,?>)jobs.get(null)).isEmpty(),"locate does not enqueue hidden template generation");
  current="dimension_transfer";var original=YagaData.get(w);var nether=w.getServer().getLevel(Level.NETHER);p.teleportTo(nether,0.5,100,0.5,p.getYRot(),p.getXRot());check(YagaData.get(p.serverLevel())==original,"Yaga progress shared across actual Nether transfer");p.teleportTo(w,1000.5,201,0.5,0,0);check(p.serverLevel()==w,"returned to Overworld");
 }
 static void consumables(){current="yaga_consumable_effects";p.removeAllEffects();p.getInventory().clearContent();for(var brew:YagaServices.BREWS){var item=brew.output().getItem();p.removeAllEffects();p.addEffect(new net.minecraft.world.effect.MobEffectInstance(net.minecraft.world.effect.MobEffects.POISON,100));long now=w.getGameTime();p.getPersistentData().putLong("YagaFlightRecovery",now+60);var stack=new ItemStack(item,2);var result=item.finishUsingItem(stack,w,p);check(result.getCount()==1&&result.is(item),"Survival consumes exactly one "+brew.id);switch(brew.id){case "otvar_ochishcheniya":check(!p.hasEffect(net.minecraft.world.effect.MobEffects.POISON),"cleansing removes real poison");break;case "letuchaya_maz":check(p.getPersistentData().getLong("YagaFlightSalve")==now+6000&&p.getPersistentData().getLong("YagaFlightRecovery")==now+30,"salve applies6000ticks and halves real recovery");break;default:var effect=switch(brew.id){case "otvar_lesnoy_zorkosti"->net.minecraft.world.effect.MobEffects.NIGHT_VISION;case "yagin_nastoy_stoykosti"->net.minecraft.world.effect.MobEffects.DAMAGE_RESISTANCE;case "otvar_bodrosti"->net.minecraft.world.effect.MobEffects.DIG_SPEED;default->net.minecraft.world.effect.MobEffects.REGENERATION;};int duration=brew.id.equals("yagin_nastoy_stoykosti")?600:brew.id.equals("lesnoy_nastoy_vosstanovleniya")?200:1200;check(p.hasEffect(effect)&&p.getEffect(effect).getDuration()==duration,"native expected effect/duration "+brew.id);}int bottles=p.getInventory().countItem(Items.GLASS_BOTTLE);check(bottles==(brew.id.equals("letuchaya_maz")?0:1),"correct remainder "+brew.id);p.getInventory().clearContent();}p.removeAllEffects();}
 static void extended()throws Exception{
  if(!extended){extended=true;services();consumables();current="sivka_hover_and_control";scene(1);return;}caseTick++;h.input(new SivkaNetwork.Input(h.getId(),caseTick,caseTick<=100?1:0,0,0,caseTick<=100,false,false));if(caseTick==100){out.put("brake_release_entity_tick",h.tickCount);out.put("brake_release_y",h.getY());out.put("brake_release_pos",h.position().toString());check(h.actualSpeed()>=39,"full-speed braking setup reaches40blocks/s");}
  if(caseTick==140){out.put("brake_final_entity_tick",h.tickCount);out.put("brake_final_y",h.getY());out.put("brake_initial_y",y0);out.put("brake_final_speed",h.actualSpeed());out.put("brake_final_pos",h.position().toString());check(h.actualSpeed()<.5&&Math.abs(h.getY()-y0)<.5,"release input brakes to hover without forced descent");check(Math.abs(h.getYRot())<1,"mounted AI cannot turn horse away from rider yaw");p.stopRiding();h.setPos(1000.5,201,.5);h.setOnGround(true);p.moveTo(1001.5,201,.5);var b=SivkaBonds.get(w).bonds.get(p.getUUID());b.stage=6;b.play=1000;b.lastFeed=0;var idle=SivkaEntity.class.getDeclaredField("idleTicks");idle.setAccessible(true);idle.setInt(h,SivkaRules.DEPART_DELAY-1);current="sivka_feeding";var food=new ItemStack(Items.GOLDEN_APPLE);check(SivkaBonds.get(w).feed(p,h,food),"seventh real feeding accepted near departure deadline");check(food.isEmpty()&&b.stage==7,"feeding consumes once and completes permanent bond");}
  if(caseTick==175){check(!h.isRemoved(),"feeding renews idle timer and prevents immediate disappearance");h.setPos(1000.5,220,.5);p.startRiding(h,true);var n=new CompoundTag();h.addAdditionalSaveData(n);n.putBoolean("SivkaAirborne",true);h.readAdditionalSaveData(n);current="sivka_actual_logout_save";UUID horse=h.getUUID();long generation=h.generation;w.getServer().getPlayerList().remove(p);var file=w.getServer().getWorldPath(net.minecraft.world.level.storage.LevelResource.PLAYER_DATA_DIR).resolve(p.getUUID()+".dat");try(var in=Files.newInputStream(file)){var tag=NbtIo.readCompressed(in,NbtAccounter.unlimitedHeap());check(tag.contains("RootVehicle")&&tag.getCompound("RootVehicle").getCompound("Entity").hasUUID("SivkaOwner"),"actual PlayerList.remove saves mounted Sivka in player RootVehicle");check(tag.getCompound("RootVehicle").getUUID("Attach").equals(horse),"saved attach UUID matches canonical horse");}check(SivkaBonds.get(w).bonds.get(p.getUUID()).generation==generation,"logout preserves canonical generation");out.put("player_uuid",p.getUUID().toString());out.put("horse_uuid",horse.toString());finish(null);}
 }
 static void restartSetup()throws Exception{current="restart_setup";p=player("Stabilization269");var file=w.getServer().getWorldPath(net.minecraft.world.level.storage.LevelResource.PLAYER_DATA_DIR).resolve(p.getUUID()+".dat");try(var in=Files.newInputStream(file)){var n=NbtIo.readCompressed(in,NbtAccounter.unlimitedHeap());p.load(n);var root=n.getCompound("RootVehicle");var entity=EntityType.loadEntityRecursive(root.getCompound("Entity"),w,e->{w.getChunkAt(e.blockPosition());return e;});check(entity instanceof SivkaEntity,"real process restart loaded saved Sivka root type");h=(SivkaEntity)entity;check(w.addFreshEntity(h),"canonical saved root added without duplicate");check(h.getUUID().equals(root.getUUID("Attach"))&&h.owns(p),"saved UUID/bond/generation remain valid");check(p.startRiding(h,true),"native player can reattach to saved mount");}var data=YagaData.get(w);check(data.placed&&data.npc!=null,"Yaga placed flag/NPC UUID persisted");w.getChunkAt(data.anchor);out.put("Yaga_anchor",data.anchor.toShortString());}
 @SubscribeEvent public static void started(net.neoforged.neoforge.event.server.ServerStartedEvent e){w=e.getServer().overworld();start=System.nanoTime();try{registry();if("frequency".equals(System.getProperty("slavicmyths.qa269"))){Frequency269.init();return;}if(System.getProperty("slavicmyths.qa269","").startsWith("native-ritual")){NativeRitual269.run(System.getProperty("slavicmyths.qa269").endsWith("restart"));finish(null);return;}if("census".equals(System.getProperty("slavicmyths.qa269"))){Census269.run();finish(null);return;}if("natural".equals(System.getProperty("slavicmyths.qa269"))){Natural269.init();return;}if("natural-deep".equals(System.getProperty("slavicmyths.qa269"))){Natural269.initDeep();return;}if("restart".equals(System.getProperty("slavicmyths.qa269"))){restartSetup();return;}p=player("Stabilization269");if("terrainbench".equals(System.getProperty("slavicmyths.qa269"))){TerrainBench269.run();finish(null);return;}if("oldsave".equals(System.getProperty("slavicmyths.qa269"))){OldSave269.run();finish(null);return;}if("winters".equals(System.getProperty("slavicmyths.qa269"))){Winters269.run();finish(null);return;}if("foods".equals(System.getProperty("slavicmyths.qa269"))){Foods269.run();finish(null);return;}if("recipes".equals(System.getProperty("slavicmyths.qa269"))){Recipes269.run();finish(null);return;}if("quests".equals(System.getProperty("slavicmyths.qa269"))){w.getChunkAt(YagaData.get(w).anchor);return;}if("braking".equals(System.getProperty("slavicmyths.qa269"))){for(int z=-1;z<=16;z++){w.getChunk(62,z);w.setChunkForced(62,z,true);}scene(1);which=4;extended=true;return;}for(int x=980;x<=1100;x++)for(int z=-20;z<=120;z++){w.getChunk(x>>4,z>>4);w.setChunkForced(x>>4,z>>4,true);w.setBlock(new BlockPos(x,200,z),Blocks.STONE.defaultBlockState(),2);}yaga();current="sivka_jump";scene(0);}catch(Throwable ex){finish(ex);}}
 @SubscribeEvent public static void before(net.neoforged.neoforge.event.tick.ServerTickEvent.Pre e){pre=System.nanoTime();}
 @SubscribeEvent public static void tick(net.neoforged.neoforge.event.tick.ServerTickEvent.Post e){if(w==null||done)return;times.add(System.nanoTime()-pre);ticks++;try{if("frequency".equals(System.getProperty("slavicmyths.qa269"))){Frequency269.tick();return;}if(System.getProperty("slavicmyths.qa269","").startsWith("natural")){Natural269.tick();return;}if("restart".equals(System.getProperty("slavicmyths.qa269"))){if(ticks>=60){current="restart_state";check(!h.isRemoved()&&p.getVehicle()==h&&h.owns(p),"saved flying horse remains present and mounted60ticks after process restart");check(w.getEntity(YagaData.get(w).npc) instanceof BabaYaga,"actual saved Yaga NPC loaded, not just a flag");check(YagaData.get(w).progress(p.getUUID()).stage==3,"earned/saved Yaga trust survives process restart");finish(null);}return;}if("quests".equals(System.getProperty("slavicmyths.qa269"))){if(ticks>=60){Quests269.run();finish(null);}return;}if("braking".equals(System.getProperty("slavicmyths.qa269"))){extended();return;}if(System.nanoTime()-start>360_000_000_000L)throw new IllegalStateException("timeout "+current);if(which<4){caseTick++;if(which==0){h.input(new SivkaNetwork.Input(h.getId(),caseTick,0,0,0,false,caseTick<4,false));peak=Math.max(peak,h.getY());if(caseTick==32){check(peak-y0>=1.1,"normal ground jump clears one block; peak="+(peak-y0));which++;current="sivka_takeoff";scene(0);}}
   else if(which==1){h.input(new SivkaNetwork.Input(h.getId(),caseTick,1,0,0,true,caseTick<6,false));if(caseTick==20){check(h.flying(),"sprint+jump takes off within20ticks without long runway");which++;current="sivka_flight";scene(1);}}
   else if(which==2){h.input(new SivkaNetwork.Input(h.getId(),caseTick,1,0,0,true,false,false));maxSpeed=Math.max(maxSpeed,h.actualSpeed());if(caseTick==100){check(maxSpeed>=30,"controlled flight reaches30blocks/s; observed="+maxSpeed);which++;current="sivka_logout";SivkaBonds.logout(new net.neoforged.neoforge.event.entity.player.PlayerEvent.PlayerLoggedOutEvent(p));check(!h.isRemoved()&&SivkaBonds.get(w).bonds.get(p.getUUID()).entity!=null,"logout does not delete mounted horse/bond");which=4;}}
  }else{if(YagaData.get(w).placed){extended();}else if(!YagaDiscovery.active(w.getServer())){check(false,"Yaga discovery ended without actual house: "+YagaData.get(w).placed);finish(null);}}
 }catch(Throwable ex){finish(ex);}}
 static void finish(Throwable error){done=true;try{out.put("scenario",System.getProperty("slavicmyths.qa269"));out.put("seed",w==null?0:w.getSeed());out.put("checks",checks);out.put("status",error!=null||checks.stream().anyMatch(c->c.get("status").equals("FAIL"))?"FAIL":"PASS");out.put("error",error==null?null:error.toString());out.put("ticks",ticks);var sorted=new ArrayList<>(times);Collections.sort(sorted);out.put("p95_tick_ms",sorted.isEmpty()?0:sorted.get((int)(sorted.size()*.95))/1e6);out.put("elapsed_seconds",(System.nanoTime()-start)/1e9);Files.writeString(Path.of("stabilization269.json"),new com.google.gson.GsonBuilder().setPrettyPrinting().create().toJson(out));System.out.println("STABILIZATION269 "+out.get("status"));if(error!=null)error.printStackTrace();}catch(Exception ex){ex.printStackTrace();}if(w!=null){w.getServer().saveEverything(false,true,true);w.getServer().halt(false);}}
}
